<script setup lang="ts">
import { computed, nextTick, ref, watch, useId, defineAsyncComponent } from 'vue'
import { Send, Sparkles } from '@lucide/vue'
import { useSolStore, useSystemStore, useInterfaceStore, useTradeStore, useKronosStore } from '../stores'
const SolMessage=defineAsyncComponent(()=>import('./SolMessage.vue'))
const sol = useSolStore(); const system = useSystemStore(); const input = ref(''); const scroll = ref<HTMLElement>()
const ui=useInterfaceStore();const trades=useTradeStore();const kronos=useKronosStore()
const questions=computed(()=>[`Dame los resultados de ${ui.profile.replace('EURUSD_','')}`, 'Compara R1, R5 y R10', '¿Por qué no entramos?', `Grafica el drawdown de ${ui.profile.replace('EURUSD_','')}`, kronos.view?.latest?'¿Qué está viendo Kronos?':'¿Qué evidencia falta para Kronos?', trades.open.length?'¿Qué operación está abierta?':'¿Por qué no hay operación abierta?'])
const inputId=useId()
async function send(question = input.value) { input.value = ''; await sol.send(question); await nextTick(); if (scroll.value) scroll.value.scrollTop = scroll.value.scrollHeight }
watch(() => sol.busy, async () => { await nextTick(); if (scroll.value) scroll.value.scrollTop = scroll.value.scrollHeight })
</script>
<template><section class="sol-chat"><header class="sol-heading"><span class="sol-avatar"><Sparkles :size="22" /></span><div><h3>Sol <span class="small muted">Research assistant</span></h3><p>{{ system.status?.solBudget===0?'LOCAL EVIDENCE · GPT inactivo':system.status?.sol ?? 'UNKNOWN' }} · sin autoridad de ejecución</p></div></header><div ref="scroll" class="chat-scroll" aria-live="polite"><div v-if="!sol.messages.length" class="chat-welcome"><span class="eyebrow">EVIDENCIA, ANTES QUE INTUICIÓN</span><h2>¿Qué quieres entender<br>del laboratorio?</h2><p>Resultados reales del proyecto. Fills shadow y métricas insuficientes se identifican explícitamente.</p><div class="suggestions"><button v-for="q in questions" :key="q" @click="send(q)">{{ q }} <span>↗</span></button></div></div><div v-for="message in sol.messages" :key="message.id" class="chat-exchange"><p class="user-message">{{ message.question }}</p><SolMessage v-if="message.response" :response="message.response" /><p v-if="message.error" role="alert" class="notice">{{ message.error }}</p></div><div v-if="sol.busy" class="sol-loading" role="status"><span class="skeleton"></span><span>Consultando evidencia…</span></div></div><footer><div class="chat-budget">{{ system.status?.sol ?? 'DATA_UNAVAILABLE' }} · presupuesto configurado US${{ system.status?.solBudget ?? 'UNKNOWN' }}</div><form @submit.prevent="send()"><label class="sr-only" :for="inputId">Pregunta a Sol</label><textarea :id="inputId" v-model="input" maxlength="1000" rows="2" placeholder="Pregunta sobre R1, R5, R10 o el mercado…" :disabled="sol.busy" @keydown.enter.exact.prevent="send()"></textarea><button class="primary-button" :disabled="sol.busy || !input.trim()" aria-label="Enviar pregunta"><Send :size="18" /></button></form><small>Sin órdenes, cambios de riesgo ni promociones. Enter envía; Shift+Enter añade una línea.</small></footer></section></template>
